using System.ComponentModel.DataAnnotations;

namespace SalesEstimateService.API.Models
{
    public enum SalesEstimateStatus
    {
        Draft = 0,
        Sent = 1,
        Accepted = 2,
        Declined = 3,
        Cancelled = 4,
        Converted = 5
    }

    public class SalesEstimate
    {
        [Key]
        public int Id { get; set; }

        public Guid ClientId { get; set; }

        // Generated by the backend when the estimate is sent.
        [MaxLength(50)]
        public string? EstimateNumber { get; set; }

        [Required]
        [MaxLength(200)]
        public string ClientName { get; set; } = string.Empty;

        [MaxLength(200)]
        public string CompanyName { get; set; } = string.Empty;

        [MaxLength(1000)]
        public string BillingAddress { get; set; } = string.Empty;

        public DateOnly EstimateDate { get; set; }

        public DateOnly ValidUntil { get; set; }

        public DateOnly? ServicePeriodStart { get; set; }

        public DateOnly? ServicePeriodEnd { get; set; }

        [Required]
        [MaxLength(3)]
        public string Currency { get; set; } = string.Empty;

        [Required]
        [MaxLength(20)]
        public string Branch { get; set; } = string.Empty;

        // Calculated by the backend from estimate items.
        public decimal SubTotal { get; set; }

        public decimal DiscountTotal { get; set; }

        public decimal TaxTotal { get; set; }

        public decimal GrandTotal { get; set; }

        public SalesEstimateStatus Status { get; set; } =
            SalesEstimateStatus.Draft;

        [MaxLength(2000)]
        public string Notes { get; set; } = string.Empty;

        [MaxLength(2000)]
        public string AdditionalTerms { get; set; } = string.Empty;

        public DateTime CreatedDate { get; set; } =
            DateTime.UtcNow;

        public DateTime? ModifiedDate { get; set; }

        public DateTime? SentDate { get; set; }

        public DateTime? AcceptedDate { get; set; }

        public DateTime? DeclinedDate { get; set; }

        public DateTime? CancelledDate { get; set; }

        // External invoice ID; there is no cross-service navigation property.
        public int? ConvertedInvoiceId { get; set; }

        public DateTime? ConvertedDate { get; set; }

        [Timestamp]
        public byte[] RowVersion { get; set; } = [];

        public ICollection<SalesEstimateItem> Items { get; set; } =
            new List<SalesEstimateItem>();
    }
}
